"/* ==========================================================================
   Recipe Categories — Page-Specific Stylesheet
   File: css/recipe-categories.css

   This file styles ONLY the Recipe Categories page.
   It does NOT override or replace css/style.css.
   It uses the same CSS colour variables defined in style.css:
     --cream, --forest-green, --sage-green, --warm-peach, --dark-brown
   ========================================================================== */


/* --------------------------------------------------------------------------
   1. Page Hero (Heading & Subtitle)
   Centred layout matching the prototype.
   -------------------------------------------------------------------------- */
.categories-hero {
  text-align: center;
  padding-block: 2rem 1rem;
}

.categories-heading {
  font-size: 2.4rem;
  font-family: var(--font-heading);
  color: var(--forest-green);
  margin-bottom: 0.5rem;
  letter-spacing: 0.03em;
}

.categories-subtitle {
  font-size: 1.1rem;
  color: var(--sage-green);
  margin-bottom: 0;
  font-weight: 500;
}


/* --------------------------------------------------------------------------
   2. Search & Filter Controls Bar
   Horizontal row on desktop, stacks neatly on mobile.
   -------------------------------------------------------------------------- */
.categories-controls {
  display: flex;
  flex-wrap: wrap;          /* wraps to next line on small screens */
  align-items: flex-end;    /* align labels + inputs along the bottom */
  gap: 1rem;
  padding: 1.25rem 1.5rem;
  background-color: #fff;
  border: 1px solid var(--sage-green);
  border-radius: var(--radius-md);
  margin-bottom: 2rem;
}

/* Each label+input pair is a "control group" */
.control-group {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

/* The search input group grows to fill leftover space */
.control-group:first-child {
  flex: 1;
  min-width: 200px;
}

